def _iar_inventory(root, *, entries=None):
    result = original_inventory(root, entries=entries)
    return {k: (v, (Path(root) / k).lstat().st_mtime_ns) for k, v in result.items()}

def _iar_resolve_alternates(original, copied):
    path = copied / 'info/alternates'
    if path.exists():
        _iar_write_alternates(path, [(original / line).resolve() for line in path.read_text().splitlines()])

def _iar_copy_entry(source, target, *, skip=()):
    if source.is_dir():
        target.mkdir(parents=True, exist_ok=True)
        for child in source.iterdir(): _iar_copy_entry(child, target / child.name)
        _iar_sh.copystat(source, target)
    else: _iar_sh.copy2(source, target)

def _iar_live_inventory(root):
    result = original_live_inventory(root)
    if _iar_git_dirs(root)[0] == _iar_git_dirs(root)[1]:
        result = {k: v for k, v in result.items() if not k.startswith('git-dir/sharedindex.')}
    return result
